import json, re, time
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen

BASE = 'http://localhost:8080'

def wait_seconds(headers, body):
    raw = headers.get('Retry-After') or headers.get('X-Retry-After')
    if raw:
        try:
            return max(0.0, float(raw))
        except ValueError:
            pass
    try:
        obj = json.loads(body.decode('utf-8'))
        for key in ('retry_after', 'wait_seconds', 'wait'):
            if key in obj:
                return max(0.0, float(obj[key]))
        msg = str(obj)
    except Exception:
        msg = body.decode('utf-8', 'replace')
    m = re.search(r'(?:wait|retry)["'^0-9]*('"\\d+(?:\\.\\d+)?)', msg, re.I)
    return float(m.group(1)) if m else 1.0

token = None

def get_token():
    global token
    while True:
        try:
            req = Request(BASE + '/token', method='POST')
            with urlopen(req, timeout=30) as resp:
                token = [REDACTED_SECRET]'token']
                return
        except (HTTPError, URLError, TimeoutError) as e:
            if isinstance(e, HTTPError):
                body = e.read()
                delay = wait_seconds(e.headers, body) if e.code == 429 else 1.0
            else:
                delay = 1.0
            time.sleep(delay)

def api_get(path):
    global token
    while True:
        if token is None:
            get_token()
        try:
            req = Request(BASE + path, headers={'Authorization': 'Bearer ' + token})
            with urlopen(req, timeout=30) as resp:
                return json.load(resp)
        except HTTPError as e:
            body = e.read()
            if e.code == 401:
                token = None
                continue
            if e.code == 429:
                time.sleep(wait_seconds(e.headers, body))
                continue
            time.sleep(1.0)
        except (URLError, TimeoutError):
            time.sleep(1.0)

seen = set()
orders = []
duplicates = 0
path = '/orders?page=1'
pages = 0
raw_items = 0
while path:
    data = api_get(path)
    pages += 1
    raw_items += len(data.get('items', []))
    for order in data.get('items', []):
        oid = order['id']
        if oid in seen:
            duplicates += 1
            continue
        seen.add(oid)
        orders.append(order)
    path = data.get('next')

start = datetime(2025, 3, 1, tzinfo=timezone.utc)
end = datetime(2025, 6, 1, tzinfo=timezone.utc)
qualifying = []
for order in orders:
    if order['status'] "'!= '"'shipped':
        continue
    dt_text = order['placed_at'].replace('Z', '+00:00')
    dt = datetime.fromisoformat(dt_text).astimezone(timezone.utc)
    if start <= dt < end:
        qualifying.append(order)

customers = {}
by_region = {'north': 0, 'south': 0, 'east': 0, 'west': 0}
for order in qualifying:
    cid = order['customer_id']
    if cid not in customers:
        customers[cid] = api_get('/customers/' + cid)
    customer = customers[cid]
    pct = int(customer['discount_pct'])
    discounted = (Decimal(order['amount_cents']) * (Decimal(100 - pct) / Decimal(100))).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
    by_region[customer['region']] += int(discounted)

total = sum(by_region.values())
print(json.dumps({
    'pages': pages,
    'raw_items': raw_items,
    'distinct_listings': len(orders),
    'duplicates_skipped': duplicates,
    'qualifying_orders': len(qualifying),
    'customers_fetched': len(customers),
    'total_cents': total,
    'by_region': by_region,
    'sum_check': sum(by_region.values()) == total,
}, sort_keys=True))
